import { useState } from 'react';
import './App.css';

const avatarOptions = [
  { id: 'coral', label: 'Coral', initials: 'C', className: 'avatar--coral' },
  { id: 'teal', label: 'Teal', initials: 'T', className: 'avatar--teal' },
  { id: 'stone', label: 'Stone', initials: 'S', className: 'avatar--stone' },
  { id: 'navy', label: 'Navy', initials: 'N', className: 'avatar--navy' },
];

function App() {
  const [activeView, setActiveView] = useState('signup');
  const [formData, setFormData] = useState({
    username: '',
    bio: '',
    avatarId: avatarOptions[0].id,
  });
  const [profile, setProfile] = useState(null);

  const selectedAvatar =
    avatarOptions.find((option) => option.id === formData.avatarId) ||
    avatarOptions[0];

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const handleAvatarSelect = (avatarId) => {
    setFormData((current) => ({
      ...current,
      avatarId,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    const username = formData.username.trim();
    const bio = formData.bio.trim();

    if (!username || !bio) {
      return;
    }

    setProfile({
      username,
      bio,
      avatar: selectedAvatar,
    });
  };

  return (
    <div className="page">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true" />
          <span>Media Journal</span>
        </div>

        <nav className="auth-nav" aria-label="Authentication options">
          <button
            type="button"
            className={`nav-button${activeView === 'login' ? ' is-active' : ''}`}
            onClick={() => setActiveView('login')}
            aria-pressed={activeView === 'login'}
          >
            Log in
          </button>
          <button
            type="button"
            className={`nav-button${activeView === 'signup' ? ' is-active' : ''}`}
            onClick={() => setActiveView('signup')}
            aria-pressed={activeView === 'signup'}
          >
            Sign up
          </button>
        </nav>
      </header>

      <main className="app">
        <section className="card">
          {activeView === 'signup' ? (
            <>
              <div className="card-header">
                <p className="eyebrow">Account setup</p>
                <h1>Create your profile</h1>
                <p className="subcopy">
                  Start with a username, short bio, and avatar. Media history
                  and community tools are placeholders for now.
                </p>
              </div>

              <form className="form" onSubmit={handleSubmit}>
                <label className="field">
                  <span>Username</span>
                  <input
                    name="username"
                    type="text"
                    placeholder="moviefan"
                    value={formData.username}
                    onChange={handleChange}
                    maxLength="24"
                    required
                  />
                </label>

                <label className="field">
                  <span>Bio</span>
                  <textarea
                    name="bio"
                    placeholder="Share a short note about what you like."
                    value={formData.bio}
                    onChange={handleChange}
                    rows="4"
                    maxLength="160"
                    required
                  />
                </label>

                <fieldset className="field avatar-field">
                  <legend>Avatar</legend>

                  <div className="avatar-list">
                    {avatarOptions.map((option) => {
                      const isSelected = option.id === formData.avatarId;

                      return (
                        <button
                          key={option.id}
                          type="button"
                          className={`avatar-option${
                            isSelected ? ' is-selected' : ''
                          }`}
                          onClick={() => handleAvatarSelect(option.id)}
                          aria-pressed={isSelected}
                        >
                          <span
                            className={`avatar-swatch ${option.className}`}
                            aria-hidden="true"
                          >
                            {option.initials}
                          </span>
                          <span>{option.label}</span>
                        </button>
                      );
                    })}
                  </div>
                </fieldset>

                <button className="primary-button" type="submit">
                  {profile ? 'Update profile' : 'Create profile'}
                </button>
              </form>

              <section className="summary" aria-label="Profile summary">
                <div
                  className={`summary-avatar ${(
                    profile?.avatar || selectedAvatar
                  ).className}`}
                  aria-hidden="true"
                >
                  {(profile?.avatar || selectedAvatar).initials}
                </div>

                <div>
                  <h2>{profile ? `@${profile.username}` : '@your_name'}</h2>
                  <p>
                    {profile
                      ? profile.bio
                      : 'Your username, bio, and avatar preview will appear here.'}
                  </p>
                  {profile ? (
                    <p className="status" role="status">
                      Profile created locally.
                    </p>
                  ) : null}
                </div>
              </section>
            </>
          ) : (
            <section className="placeholder-panel">
              <div className="card-header">
                <p className="eyebrow">Login</p>
                <h1>Log in will live here</h1>
                <p className="subcopy">
                  Login is not built yet. Use the Sign up tab to create a basic
                  local profile for now.
                </p>
              </div>

              <div className="placeholder-box">
                <p>Email and password fields coming soon.</p>
                <p>Saved media history and community access coming soon.</p>
              </div>
            </section>
          )}
        </section>
      </main>
    </div>
  );
}

export default App;
